CREATE TABLE IF NOT EXISTS client (id TEXT PRIMARY KEY, name TEXT NOT NULL, display_name TEXT, identifier TEXT NOT NULL UNIQUE, config_path TEXT, config_mode TEXT CHECK (config_mode IN ('unify','hosted','transparent')), transport TEXT NOT NULL DEFAULT 'auto' CHECK (transport IN ('auto', 'sse', 'stdio', 'streamable_http')), client_version TEXT, backup_policy TEXT NOT NULL DEFAULT 'keep_n' CHECK (backup_policy IN ('keep_last', 'keep_n', 'off')), backup_limit INTEGER DEFAULT 5, capability_source TEXT NOT NULL DEFAULT 'activated' CHECK (capability_source IN ('activated', 'profiles', 'custom')), unify_route_mode TEXT NOT NULL DEFAULT 'broker_only' CHECK (unify_route_mode IN ('broker_only', 'server_level', 'capability_level')), governance_kind TEXT NOT NULL DEFAULT 'passive' CHECK (governance_kind IN ('passive', 'active')), connection_mode TEXT NOT NULL DEFAULT 'local_config_detected' CHECK (connection_mode IN ('local_config_detected', 'manual')), registration_origin TEXT NOT NULL DEFAULT 'manual' CHECK (registration_origin IN ('manual', 'config_detection', 'runtime_initialize')), runtime_observed INTEGER NOT NULL DEFAULT 0 CHECK (runtime_observed IN (0, 1)), template_identifier TEXT, selected_profile_ids TEXT, custom_profile_id TEXT, approval_status TEXT NOT NULL DEFAULT 'approved' CHECK (approval_status IN ('pending', 'approved', 'suspended')), template_id TEXT, template_version TEXT, approval_metadata TEXT, config_format TEXT, protocol_revision TEXT, container_type TEXT, container_keys TEXT, storage_kind TEXT, storage_adapter TEXT, storage_path_strategy TEXT, merge_strategy TEXT, keep_original_config INTEGER, managed_source TEXT, transports TEXT, config_file_parse TEXT, attachment_state TEXT NOT NULL DEFAULT 'not_applicable' CHECK (attachment_state IN ('attached', 'detached', 'not_applicable')), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS client_template_runtime (identifier TEXT PRIMARY KEY, payload_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS client_writeback_policy (client_identifier TEXT PRIMARY KEY, merge_strategy TEXT NOT NULL CHECK (merge_strategy IN ('replace', 'deep_merge')), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (client_identifier) REFERENCES client(identifier) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS client_runtime_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL CHECK (key != 'default_config_mode' OR value IN ('unify', 'hosted', 'transparent')));
